  background: #fffaf5;
  border: 1px solid #fed7aa;
}
.remains-tag {
  font-size: 0.7rem;
  font-weight: 700;
  color: #c2410c;
  text-transform: uppercase;
  display: inline-block;
  margin-bottom: 0.25rem;
}
.table-container {
  overflow-x: auto;
  margin: 1rem 0;
  border-radius: 10px;
  border: 1px solid #e2e8f0;
}
table.custom-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.9rem;
}
table.custom-table th {
  background: #f1f5f9;
  color: #1e293b;
  padding: 0.65rem 0.8rem;
  border-bottom: 2px solid #cbd5e1;
  font-weight: 700;
}
table.custom-table td {
  padding: 0.65rem 0.8rem;
  border-bottom: 1px solid #e2e8f0;
  line-height: 1.55;
}
.applied-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.75rem;
}
.applied-tag {
  background: #f1f5f9;
  color: #334155;
  font-size: 0.8rem;
  font-weight: 600;
